"""Tokenizer and recursive-descent parser for minisql SELECT queries.

The public entry point is :func:`parse`, which turns one query string into
an :class:`minisql.ast.Query`.  Syntax problems are reported as
:class:`minisql.errors.QueryError`.
"""

from dataclasses import dataclass
from typing import Any, List, Optional

from . import ast
from .errors import QueryError


KEYWORDS = frozenset(
    {
        "SELECT",
        "DISTINCT",
        "FROM",
        "WHERE",
        "GROUP",
        "BY",
        "HAVING",
        "ORDER",
        "LIMIT",
        "OFFSET",
        "AS",
        "ASC",
        "DESC",
        "AND",
        "OR",
        "NOT",
        "NULL",
        "TRUE",
        "FALSE",
        "IS",
        "IN",
        "BETWEEN",
        "LIKE",
    }
)

_COMPARISON_OPS = frozenset({"!=", "<>", "<", "<=", ">"})
_SINGLE_SYMBOLS = frozenset("(),;*+-/=<>")
_TWO_CHAR_SYMBOLS = frozenset({"<=", ">=", "!=", "<>", "||"})


@dataclass
class _Token:
    kind: str  # NAME, QNAME, STRING, NUMBER, SYMBOL or EOF
    value: Any
    raw: str
    start: int
    end: int


def _is_ascii_letter(ch: str) -> bool:
    return ("a" <= ch <= "z") or ("A" <= ch <= "Z")


def _is_ascii_digit(ch: str) -> bool:
    return "0" <= ch <= "9"


def _is_name_start(ch: str) -> bool:
    return _is_ascii_letter(ch) or ch == "_"


def _is_name_part(ch: str) -> bool:
    return _is_name_start(ch) or _is_ascii_digit(ch)


def _syntax(message: str, position: Optional[int] = None) -> QueryError:
    if position is None:
        return QueryError(message)
    return QueryError("{} at position {}".format(message, position + 1))


def _tokenize(sql: str) -> List[_Token]:
    tokens: List[_Token] = []
    length = len(sql)
    i = 0

    while i < length:
        ch = sql[i]

        if ch.isspace():
            i += 1
            continue

        if _is_name_start(ch):
            start = i
            i += 1
            while i < length and _is_name_part(sql[i]):
                i += 1
            raw = sql[start:i]
            tokens.append(_Token("NAME", raw, raw, start, i))
            continue

        if ch == '"':
            start = i
            i += 1
            parts = []
            while True:
                if i >= length:
                    raise _syntax("unterminated quoted identifier", start)
                current = sql[i]
                if current == '"':
                    if i + 1 < length and sql[i + 1] == '"':
                        parts.append('"')
                        i += 2
                        continue
                    i += 1
                    break
                parts.append(current)
                i += 1
            tokens.append(_Token("QNAME", "".join(parts), sql[start:i], start, i))
            continue

        if ch == "'":
            start = i
            i += 1
            parts = []
            while True:
                if i >= length:
                    raise _syntax("unterminated string literal", start)
                current = sql[i]
                if current == "'":
                    if i + 1 < length and sql[i + 1] == "'":
                        parts.append("'")
                        i += 2
                        continue
                    i += 1
                    break
                parts.append(current)
                i += 1
            tokens.append(_Token("STRING", "".join(parts), sql[start:i], start, i))
            continue

        if _is_ascii_digit(ch) or (
            ch == "." and i + 1 < length and _is_ascii_digit(sql[i + 1])
        ):
            start = i
            is_float = False
            if ch == ".":
                is_float = True
                i += 1
                while i < length and _is_ascii_digit(sql[i]):
                    i += 1
            else:
                while i < length and _is_ascii_digit(sql[i]):
                    i += 1
                if i < length and sql[i] == ".":
                    is_float = True
                    i += 1
                    while i < length and _is_ascii_digit(sql[i]):
                        i += 1
            raw = sql[start:i]
            value = float(raw) if is_float else int(raw)
            tokens.append(_Token("NUMBER", value, raw, start, i))
            continue

        if i + 1 < length and sql[i : i + 2] in _TWO_CHAR_SYMBOLS:
            raw = sql[i : i + 2]
            tokens.append(_Token("SYMBOL", raw, raw, i, i + 2))
            i += 2
            continue

        if ch in _SINGLE_SYMBOLS:
            tokens.append(_Token("SYMBOL", ch, ch, i, i + 1))
            i += 1
            continue

        raise _syntax("unexpected character {!r}".format(ch), i)

    tokens.append(_Token("EOF", None, "", length, length))
    return tokens


class _Parser:
    def __init__(self, sql: str) -> None:
        self.sql = sql
        self.tokens = _tokenize(sql)
        self.pos = 0

    # -- token helpers -------------------------------------------------

    def _peek(self, offset: int = 0) -> _Token:
        index = self.pos + offset
        if index >= len(self.tokens):
            return self.tokens[-1]
        return self.tokens[index]

    def _previous(self) -> _Token:
        return self.tokens[self.pos - 1]

    def _advance(self) -> _Token:
        token = self.tokens[self.pos]
        if token.kind != "EOF":
            self.pos += 1
        return token

    def _is_keyword(self, token: _Token, keyword: str) -> bool:
        return token.kind == "NAME" and token.value.upper() == keyword

    def _match_keyword(self, keyword: str) -> bool:
        if self._is_keyword(self._peek(), keyword):
            self._advance()
            return True
        return False

    def _expect_keyword(self, keyword: str) -> _Token:
        token = self._peek()
        if not self._is_keyword(token, keyword):
            raise self._unexpected("expected {}".format(keyword), token)
        return self._advance()

    def _is_symbol(self, token: _Token, symbol: str) -> bool:
        return token.kind == "SYMBOL" and token.value == symbol

    def _match_symbol(self, symbol: str) -> bool:
        if self._is_symbol(self._peek(), symbol):
            self._advance()
            return True
        return False

    def _expect_symbol(self, symbol: str) -> _Token:
        token = self._peek()
        if not self._is_symbol(token, symbol):
            raise self._unexpected("expected {!r}".format(symbol), token)
        return self._advance()

    def _span(self, start: _Token, end: _Token) -> str:
        return self.sql[start.start : end.end]

    def _unexpected(self, message: str, token: Optional[_Token] = None) -> QueryError:
        token = self._peek() if token is None else token
        if token.kind == "EOF":
            return _syntax("{} at end of input".format(message))
        return _syntax("{} near {!r}".format(message, token.raw), token.start)

    def _can_be_name(self, token: _Token) -> bool:
        if token.kind == "QNAME":
            return True
        return token.kind == "NAME" and token.value.upper() not in KEYWORDS

    def _parse_name(self) -> str:
        token = self._peek()
        if not self._can_be_name(token):
            raise self._unexpected("expected a name", token)
        self._advance()
        return token.value

    # -- expressions ---------------------------------------------------

    def _parse_expression(self) -> ast.Expr:
        return self._parse_or()

    def _parse_or(self) -> ast.Expr:
        start = self._peek()
        expr = self._parse_and()
        while self._match_keyword("OR"):
            right = self._parse_and()
            expr = ast.Binary(
                text=self._span(start, self._previous()),
                op="OR",
                left=expr,
                right=right,
            )
        return expr

    def _parse_and(self) -> ast.Expr:
        start = self._peek()
        expr = self._parse_not()
        while self._match_keyword("AND"):
            right = self._parse_not()
            expr = ast.Binary(
                text=self._span(start, self._previous()),
                op="AND",
                left=expr,
                right=right,
            )
        return expr

    def _parse_not(self) -> ast.Expr:
        if self._is_keyword(self._peek(), "NOT"):
            start = self._advance()
            operand = self._parse_not()
            return ast.Unary(
                text=self._span(start, self._previous()),
                op="NOT",
                operand=operand,
            )
        return self._parse_comparison()

    def _parse_comparison(self) -> ast.Expr:
        start = self._peek()
        left = self._parse_additive()
        token = self._peek()

        if token.kind == "SYMBOL" and (
            token.value == "=" or token.value in _COMPARISON_OPS
        ):
            op = self._advance().value
            right = self._parse_additive()
            return ast.Binary(
                text=self._span(start, self._previous()),
                op=op,
                left=left,
                right=right,
            )

        if self._match_keyword("IS"):
            negated = self._match_keyword("NOT")
            self._expect_keyword("NULL")
            return ast.IsNull(
                text=self._span(start, self._previous()),
                operand=left,
                negated=negated,
            )

        negated = False
        if (
            self._is_keyword(token, "NOT")
            and self._peek(1).kind == "NAME"
            and self._peek(1).value.upper() in ("IN", "BETWEEN", "LIKE")
        ):
            self._advance()
            negated = True
            token = self._peek()

        if self._is_keyword(token, "IN"):
            self._advance()
            self._expect_symbol("(")
            items = [self._parse_expression()]
            while self._match_symbol(","):
                items.append(self._parse_expression())
            self._expect_symbol(")")
            return ast.InList(
                text=self._span(start, self._previous()),
                operand=left,
                items=items,
                negated=negated,
            )

        if self._is_keyword(token, "BETWEEN"):
            self._advance()
            low = self._parse_additive()
            self._expect_keyword("AND")
            high = self._parse_additive()
            return ast.Between(
                text=self._span(start, self._previous()),
                operand=left,
                low=low,
                high=high,
                negated=negated,
            )

        if self._is_keyword(token, "LIKE"):
            self._advance()
            pattern = self._parse_additive()
            return ast.Like(
                text=self._span(start, self._previous()),
                operand=left,
                pattern=pattern,
                negated=negated,
            )

        return left

    def _parse_additive(self) -> ast.Expr:
        start = self._peek()
        expr = self._parse_multiplicative()
        while self._peek().kind == "SYMBOL" and self._peek().value in (
            "+",
            "-",
            "||",
        ):
            op = self._advance().value
            right = self._parse_multiplicative()
            expr = ast.Binary(
                text=self._span(start, self._previous()),
                op=op,
                left=expr,
                right=right,
            )
        return expr

    def _parse_multiplicative(self) -> ast.Expr:
        start = self._peek()
        expr = self._parse_unary()
        while self._peek().kind == "SYMBOL" and self._peek().value in ("*", "/"):
            op = self._advance().value
            right = self._parse_unary()
            expr = ast.Binary(
                text=self._span(start, self._previous()),
                op=op,
                left=expr,
                right=right,
            )
        return expr

    def _parse_unary(self) -> ast.Expr:
        if self._is_symbol(self._peek(), "-"):
            start = self._advance()
            operand = self._parse_unary()
            return ast.Unary(
                text=self._span(start, self._previous()),
                op="-",
                operand=operand,
            )
        return self._parse_primary()

    def _parse_primary(self) -> ast.Expr:
        token = self._peek()

        if token.kind == "NUMBER":
            self._advance()
            return ast.Literal(text=token.raw, value=token.value)

        if token.kind == "STRING":
            self._advance()
            return ast.Literal(text=token.raw, value=token.value)

        if token.kind == "QNAME":
            self._advance()
            return ast.Column(text=token.raw, name=token.value)

        if token.kind == "NAME":
            upper = token.value.upper()
            if upper == "NULL":
                self._advance()
                return ast.Literal(text=token.raw, value=None)
            if upper == "TRUE":
                self._advance()
                return ast.Literal(text=token.raw, value=True)
            if upper == "FALSE":
                self._advance()
                return ast.Literal(text=token.raw, value=False)
            if upper in KEYWORDS:
                raise self._unexpected(
                    "unexpected keyword {}".format(token.value.upper()), token
                )

            next_token = self._peek(1)
            if self._is_symbol(next_token, "("):
                return self._parse_call()
            self._advance()
            return ast.Column(text=token.raw, name=token.value)

        if self._is_symbol(token, "("):
            start = self._advance()
            inner = self._parse_expression()
            closing = self._expect_symbol(")")
            # A parenthesized expression keeps the parentheses in its text,
            # which is what an unnamed output column is called.
            inner.text = self.sql[start.start : closing.end]
            return inner

        raise self._unexpected("expected an expression", token)

    def _parse_call(self) -> ast.Expr:
        name_token = self._advance()
        name = name_token.value
        self._expect_symbol("(")

        if self._is_symbol(self._peek(), "*"):
            if name.upper() != "COUNT":
                raise self._unexpected(
                    "only COUNT may take '*' as an argument", self._peek()
                )
            self._advance()
            self._expect_symbol(")")
            return ast.Call(
                text=self._span(name_token, self._previous()),
                name=name,
                args=[],
                star=True,
            )

        if self._is_symbol(self._peek(), ")"):
            raise self._unexpected("function argument list cannot be empty", self._peek())

        args = [self._parse_expression()]
        while self._match_symbol(","):
            args.append(self._parse_expression())
        self._expect_symbol(")")
        return ast.Call(
            text=self._span(name_token, self._previous()),
            name=name,
            args=args,
            star=False,
        )

    # -- query clauses -------------------------------------------------

    def _parse_select_item(self) -> ast.SelectItem:
        expr = self._parse_expression()
        alias: Optional[str] = None
        if self._match_keyword("AS"):
            alias = self._parse_name()
        elif self._can_be_name(self._peek()):
            alias = self._parse_name()
        return ast.SelectItem(expr=expr, alias=alias)

    def _parse_order_item(self) -> ast.OrderItem:
        expr = self._parse_expression()
        if self._match_keyword("DESC"):
            return ast.OrderItem(expr=expr, desc=True)
        self._match_keyword("ASC")
        return ast.OrderItem(expr=expr, desc=False)

    def _parse_unsigned_integer(self) -> int:
        token = self._peek()
        if token.kind != "NUMBER" or not isinstance(token.value, int):
            raise self._unexpected("expected a non-negative integer", token)
        if isinstance(token.value, bool):  # defensive; numbers are never bools
            raise self._unexpected("expected a non-negative integer", token)
        self._advance()
        return token.value

    def parse_query(self) -> ast.Query:
        self._expect_keyword("SELECT")
        distinct = self._match_keyword("DISTINCT")

        star = False
        items: List[ast.SelectItem] = []
        if self._is_symbol(self._peek(), "*"):
            self._advance()
            star = True
        else:
            items.append(self._parse_select_item())
            while self._match_symbol(","):
                items.append(self._parse_select_item())

        self._expect_keyword("FROM")
        table = self._parse_name()

        where: Optional[ast.Expr] = None
        group_by: List[ast.Expr] = []
        having: Optional[ast.Expr] = None
        order_by: List[ast.OrderItem] = []
        limit: Optional[int] = None
        offset = 0

        if self._match_keyword("WHERE"):
            where = self._parse_expression()

        if self._match_keyword("GROUP"):
            self._expect_keyword("BY")
            group_by.append(self._parse_expression())
            while self._match_symbol(","):
                group_by.append(self._parse_expression())

        if self._match_keyword("HAVING"):
            having = self._parse_expression()

        if self._match_keyword("ORDER"):
            self._expect_keyword("BY")
            order_by.append(self._parse_order_item())
            while self._match_symbol(","):
                order_by.append(self._parse_order_item())

        if self._match_keyword("LIMIT"):
            limit = self._parse_unsigned_integer()
            if self._match_keyword("OFFSET"):
                offset = self._parse_unsigned_integer()

        self._match_symbol(";")
        if self._peek().kind != "EOF":
            raise self._unexpected("unexpected token")

        return ast.Query(
            star=star,
            items=items,
            table=table,
            distinct=distinct,
            where=where,
            group_by=group_by,
            having=having,
            order_by=order_by,
            limit=limit,
            offset=offset,
        )


def parse(sql):
    """Parse one SELECT query string and return an ast.Query.

    Raise QueryError on any syntax error.
    """

    if not isinstance(sql, str):
        raise QueryError("query must be a string")
    return _Parser(sql).parse_query()

