def _is_plain_column(expr):
    """True when ``expr`` is syntactically just a column reference.

    Parenthesized columns are still ``Column`` nodes in the AST, but their
    text includes the parentheses, which makes them ordinary expressions for
    naming purposes.
    """

    if not isinstance(expr, Column):
        return False
    text = expr.text
    if text == expr.name:
        return True
    return text == '"' + expr.name.replace('"', '""') + '"'


def _output_name(item, lookup):
    if item.alias is not None:
        return item.alias
    expr = item.expr
    if _is_plain_column(expr):
        actual = lookup.get(expr.name.lower())
        if actual is not None:
            return actual
    return expr.text


def _output_index(name, columns):
    lowered = name.lower()
    for index, column in enumerate(columns):
        if column.lower() == lowered:
            return index
    return None


class _OrderSpec:
    """How to obtain the value for one ORDER BY item."""

    __slots__ = ("kind", "index", "expr", "desc")

    def __init__(self, kind, index=None, expr=None, desc=False):
        self.kind = kind
        self.index = index
        self.expr = expr
        self.desc = desc


def _resolve_order_item(item, columns, headers, grouped, group_by):
    expr = item.expr

    if isinstance(expr, Column):
        index = _output_index(expr.name, columns)
        if index is not None:
            return _OrderSpec("output", index=index, desc=item.desc)

    if (
        isinstance(expr, Literal)
        and isinstance(expr.value, int)
        and not isinstance(expr.value, bool)
    ):
        text = expr.text or ""
        if _BARE_INT_RE.fullmatch(text):
            ordinal = int(text)
            if ordinal == expr.value:
                if ordinal < 1 or ordinal > len(columns):
                    raise QueryError(
                        "ORDER BY position %d is out of range" % ordinal
                    )
                return _OrderSpec(
                    "output", index=ordinal - 1, desc=item.desc
                )

    # It is an expression over the source rows (or groups).
    validate_expression(expr, headers, allow_aggregate=True)
    if grouped:
        validate_grouped_expression(expr, group_by)
    return _OrderSpec("expression", expr=expr, desc=item.desc)


